cd /home/sauyon/devel/dotfiles-orca-alt && python3 - <<'EOF'
p='orca.nix'; s=open(p).read()
old='''  # C-s is the shell's own search, so terminal search is left unbound.
  orcaPinned = {
    "editor.find" = [ "Ctrl+S" ];
    "browser.find" = [ "Ctrl+S" ];
    "chat.find" = [ "Ctrl+S" ];
    "settings.search" = [ "Ctrl+S" ];
'''
new='''  # C-s is the shell's own search, so terminal search is left unbound.
  #
  # Previous/next worktree, in list order, on Alt+Up/Down: the Mac chord,
  # Super+Shift+Up/Down, is Hyprland's. This one takes M-<up>/<down> from the
  # terminal, deliberately.
  orcaPinned = {
    "editor.find" = [ "Ctrl+S" ];
    "browser.find" = [ "Ctrl+S" ];
    "chat.find" = [ "Ctrl+S" ];
    "settings.search" = [ "Ctrl+S" ];
    "worktree.navigateUp" = [ "Alt+ArrowUp" ];
    "worktree.navigateDown" = [ "Alt+ArrowDown" ];
'''
assert s.count(old)==1; open(p,'w').write(s.replace(old,new))
EOF
